package Program.model;
public class Budget { private final String id,userId; private String category; private double limit;
 public Budget(String id,String userId,String category,double limit){if(limit<0)throw new IllegalArgumentException("Budget cannot be negative");this.id=id;this.userId=userId;this.category=category;this.limit=limit;} public String getId(){return id;} public String getUserId(){return userId;} public String getCategory(){return category;} public void setCategory(String v){category=v;} public double getLimit(){return limit;} public void setLimit(double v){if(v<0)throw new IllegalArgumentException("Budget cannot be negative");limit=v;} public double remaining(double spending){return limit-spending;} public double usage(double spending){return limit==0?0:Math.min(1,spending/limit);} }
